html = f'''<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Global Intentional Homicide Trends: A Multi-Dimensional Analysis (1990–2023)</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js"></script>
<style>
  :root {{
    --blue-900: #1e3a5f;
    --blue-700: #2c5f8a;
    --blue-500: #4682b4;
    --blue-200: #b8d4e8;
    --blue-50: #eef4f9;
    --red-600: #c0392b;
    --red-400: #e74c3c;
    --green-600: #27ae60;
    --gray-900: #1a1a2e;
    --gray-700: #4a4a5a;
    --gray-500: #8e8e9e;
    --gray-200: #e2e2e8;
    --gray-100: #f5f5f8;
    --white: #ffffff;
    --amber-500: #f39c12;
  }}
  * {{ margin: 0; padding: 0; box-sizing: border-box; }}
  body {{
    font-family: 'Segoe UI', system-ui, -apple-system, sans-serif;
