  }}
  .report-header .meta {{
    margin-top: 20px;
    font-size: 13px;
    opacity: 0.7;
  }}

  /* KPI dashboard */
  .kpi-dashboard {{
    display: grid;
    grid-template-columns: repeat(5, 1fr);
    gap: 16px;
    padding: 32px 56px;
    background: var(--blue-50);
    border-bottom: 1px solid var(--blue-200);
  }}
  .kpi-card {{
    background: var(--white);
    border-radius: 8px;
    padding: 20px;
    text-align: center;
    box-shadow: 0 1px 4px rgba(0,0,0,0.06);
